package com.lexorion.workforce.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;import lombok.Getter;import lombok.NoArgsConstructor;import org.hibernate.annotations.UuidGenerator;
@Entity @Table(name="employee_lifecycle_events",indexes=@Index(name="idx_lifecycle_workspace_employee_time",columnList="workspace_id,employee_id,occurred_at")) @Getter @NoArgsConstructor
public class EmployeeLifecycleEvent {@Id@UuidGenerator private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="workspace_id",nullable=false,updatable=false)private WorkforceWorkspace workspace;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="employee_id",nullable=false,updatable=false)private Employee employee;@Enumerated(EnumType.STRING)@Column(name="previous_status",length=20,updatable=false)private EmploymentStatus previousStatus;@Enumerated(EnumType.STRING)@Column(name="new_status",nullable=false,length=20,updatable=false)private EmploymentStatus newStatus;@Column(nullable=false,length=32,updatable=false)private String action;@Column(name="occurred_at",nullable=false,updatable=false)private Instant occurredAt;public EmployeeLifecycleEvent(WorkforceWorkspace w,Employee e,EmploymentStatus from,EmploymentStatus to,String a){workspace=w;employee=e;previousStatus=from;newStatus=to;action=a;occurredAt=Instant.now();}}
